#include <stdio.h>
#include <math.h>
#define W 2400
#define H 1800
double VW=2.0*W/H, VH=2.0;
// ray dir for pixel
void ray(int px,int py,double*u){
    double sx=(px+0.5)/W, sy=(py+0.5)/H;
    double dx=VW*(sx-0.5), dy=VH*(0.5-sy), dz=-1.0;
    double L=sqrt(dx*dx+dy*dy+dz*dz);
    u[0]=dx/L;u[1]=dy/L;u[2]=dz/L;
}
int hit(double cx,double cy,double cz,double R,int px,int py){
    double u[3];ray(px,py,u);
    double bx=2*(-cx*u[0]-cy*u[1]-cz*u[2]);
    double cc=cx*cx+cy*cy+cz*cz-R*R;
    double disc=bx*bx-4*cc;
    if(disc<0)return 0;
    double sq=sqrt(disc); double t=(-bx-sq)/2;
    return t>0;
}
int main(){
    // Find top, bottom, left, right silhouette for a given sphere
    double best_err=1e9; double bcx,bcy,bcz,bR;
    // center of sphere projects near screen x=1199.5 (sphere cx must be 0 for symmetry)
    // scan
    for(int zi=300;zi<=600;zi+=2){
        double cz=-zi/100.0;
        for(int yi=-80;yi<=20;yi+=2){
            double cy=yi/100.0;
            for(int ri=70;ri<=200;ri+=2){
                double R=ri/100.0;
                double cx=0;
                // top
                int top=-1,bot=-1,left=-1,right=-1;
                for(int y=750;y<1100;y++){ if(hit(cx,cy,cz,R,1200,y)){top=y;break;} }
                for(int y=1200;y>800;y--){ if(hit(cx,cy,cz,R,1200,y)){bot=y;break;} }
                for(int x=900;x<1400;x++){ if(hit(cx,cy,cz,R,x,993)){left=x;break;} }
                for(int x=1500;x>1000;x--){ if(hit(cx,cy,cz,R,x,993)){right=x;break;} }
                if(top<0)continue;
                double err=abs(top-809)+abs(bot-1177)+abs(left-1016)+abs(right-1383);
                if(err<best_err){best_err=err;bcx=cx;bcy=cy;bcz=cz;bR=R;
                    if(err<6)printf("cz=%.2f cy=%.2f R=%.2f top=%d bot=%d l=%d r=%d err=%.0f\n",cz,cy,R,top,bot,left,right,err);}
            }
        }
    }
    printf("BEST cz=%.2f cy=%.2f R=%.2f err=%.0f\n",bcz,bcy,bR,best_err);
    return 0;
}
