#include <stdio.h>
#include <math.h>
int main(){
    FILE*f=fopen("sphdata.txt","r");
    static double nx[200000],ny[200000],nz[200000],R[200000],G[200000];
    int n=0;int g,b;
    while(fscanf(f,"%lf %lf %lf %lf %d %d",&nx[n],&ny[n],&nz[n],&R[n],&g,&b)==6){G[n]=g;n++;}
    fclose(f);
    double lux=0.577350269,luy=0.577350269,luz=-0.577350269;
    // fit G = base + kd*d
    double Sx=0,Sy=0,Sxx=0,Sxy=0;
    for(int i=0;i<n;i++){double d=nx[i]*lux+ny[i]*luy+nz[i]*luz;if(d<0)d=0;Sx+=d;Sy+=G[i];Sxx+=d*d;Sxy+=d*G[i];}
    double den=n*Sxx-Sx*Sx; double kd=(n*Sxy-Sx*Sy)/den; double base=(Sy-kd*Sx)/n;
    printf("G fit: base=%.3f kd=%.3f\n",base,kd);
    // Now check for specular: compute residual at each point, see if bright points have positive residual
    double err=0; 
    for(int i=0;i<n;i++){
        double d=nx[i]*lux+ny[i]*luy+nz[i]*luz;if(d<0)d=0;
        double pr=51.0+204.0*d;
        double e=R[i]-pr; err+=e*e;
    }
    printf("R diffuse RMSE=%.3f\n",sqrt(err/n));
    // Find max residual (specular candidate)
    double maxres=-1e9; double mnx,mny,mnz;
    for(int i=0;i<n;i++){
        double d=nx[i]*lux+ny[i]*luy+nz[i]*luz;if(d<0)d=0;
        double pr=51.0+204.0*d;
        double e=R[i]-pr;
        if(e>maxres){maxres=e;mnx=nx[i];mny=ny[i];mnz=nz[i];}
    }
