#include <stdio.h>
#include <math.h>

#define W 2400
#define H 1800

int main(void){
    double VW=2.0*W/H, VH=2.0;
    double SCx=0, SCy=-0.36, SCz=-3.6, SR=0.72;
    double Lx=1, Ly=1, Lz=-1;
    double ll=sqrt(Lx*Lx+Ly*Ly+Lz*Lz);
    Lx/=ll; Ly/=ll; Lz/=ll;
    FILE*f=fopen("reconstructed.ppm","w");
    fprintf(f,"P3\n%d %d\n255\n",W,H);
    for(int py=0;py<H;py++){
        for(int px=0;px<W;px++){
            double sx=(px+0.5)/W, sy=(py+0.5)/H;
            double dx=VW*(sx-0.5), dy=VH*(0.5-sy), dz=-1.0;
            double L=sqrt(dx*dx+dy*dy+dz*dz);
            double ux=dx/L, uy=dy/L, uz=dz/L;
            double R,G,B;
            /* sphere intersection */
            double b=2*(-SCx*ux-SCy*uy-SCz*uz);
            double c=SCx*SCx+SCy*SCy+SCz*SCz-SR*SR;
            double disc=b*b-4*c;
            int sph=0; double nx=0,ny=0,nz=0;
            if(disc>=0){
                double sq=sqrt(disc);
                double t=(-b-sq)*0.5;
                if(t<=0) t=(-b+sq)*0.5;
                if(t>0){
                    nx=t*ux-SCx; ny=t*uy-SCy; nz=t*uz-SCz;
                    double nl=sqrt(nx*nx+ny*ny+nz*nz);
                    nx/=nl; ny/=nl; nz/=nl;
                    sph=1;
                }
            }
            if(sph){
                double d=nx*Lx+ny*Ly+nz*Lz; if(d<0)d=0;
                double sh=0.2+0.8*d;
                R=sh*1.0; G=sh*0.2; B=sh*0.2;
            } else if(uy<0){
                /* floor plane y=-1 */
                double t=-1.0/uy;
                double fx=t*ux, fz=t*uz;
                int chk=((int)floor(fx)+(int)floor(fz))&1;
                double al = chk?0.397:0.9;       /* dark/light albedo */
                /* floor normal (0,1,0): n.L = Ly */
                double fn = Ly; if(fn<0)fn=0;
                /* shadow? sphere blocks light */
                double sh=0.2+0.8*fn;
                double ox=fx, oy=-1.0, oz=fz;
                double sb=2*((ox*Lx+oy*Ly+oz*Lz)-(SCx*Lx+SCy*Ly+SCz*Lz));
                double sc=(ox-SCx)*(ox-SCx)+(oy-SCy)*(oy-SCy)+(oz-SCz)*(oz-SCz)-SR*SR;
                double sd=sb*sb-4*sc; /* a=1 since L normalized */
                if(sd>=0){
                    double sq=sqrt(sd); double tt=(-sb-sq)*0.5;
                    if(tt>1e-4) sh=0.2;
                }
                double v=al*sh;
                R=v; G=v; B=v;
            } else {
                double t=0.5*(uy+1.0);
                R=(1-t)+t*0.5; G=(1-t)+t*0.7; B=1.0;
            }
            int r=(int)(R*255+0.5), g=(int)(G*255+0.5), bb=(int)(B*255+0.5);
            if(r<0)r=0; if(r>255)r=255;
            if(g<0)g=0; if(g>255)g=255;
            if(bb<0)bb=0; if(bb>255)bb=255;
            fprintf(f,"%d %d %d\n",r,g,bb);
        }
    }
    fclose(f);
    return 0;
}
